const KEY='dev-master-v1';
const skills=['HTML e CSS','JavaScript','React','Backend e APIs','Banco de dados','Git e testes'];
const stages=['Salva','Preparando','Enviada','Entrevista','Encerrada'];
const defaults=()=>({profile:{name:'',role:'Desenvolvedora frontend',email:'',github:'',location:'',hours:'5',about:'',projects:''},skills:Object.fromEntries(skills.map(s=>[s,0])),assessed:false,jobs:[],tasks:{},demo:true});
let state=defaults();try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&saved.profile&&Array.isArray(saved.jobs)){state={...state,...saved,profile:{...state.profile,...saved.profile},skills:{...state.skills,...saved.skills}}}}catch{}
let storageAvailable=true;let view='inicio';let query='';let mode='Todas';
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routes=[['inicio','◫','Visão geral'],['perfil','◎','Meu perfil'],['nivel','⌘','Meu nível'],['evolucao','↗','Minha evolução'],['vagas','▣','Radar de vagas'],['candidaturas','▤','Candidaturas']];
const examples=[{id:'demo1',title:'Desenvolvedora Frontend Júnior',company:'Empresa exemplo A',mode:'Remoto',level:'Júnior',tags:['React','JavaScript','Git'],demo:true},{id:'demo2',title:'Estágio em Desenvolvimento Web',company:'Empresa exemplo B',mode:'Híbrido',level:'Estágio',tags:['HTML e CSS','JavaScript'],demo:true},{id:'demo3',title:'Desenvolvedora Full Stack Júnior',company:'Empresa exemplo C',mode:'Remoto',level:'Júnior',tags:['React','Backend e APIs','Banco de dados'],demo:true}];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true}catch{storageAvailable=false;toast('Não foi possível salvar. Exporte seus dados antes de sair.')}$('.local-pill').innerHTML=storageAvailable?'<i></i> Salvo neste navegador':'Armazenamento indisponível'}
function profileProgress(){return Math.round(['name','email','github','about','projects'].filter(k=>state.profile[k]?.trim()).length/5*100)}
function nextTasks(){const weakest=skills.slice().sort((a,b)=>state.skills[a]-state.skills[b])[0];return [{id:'profile',title:'Conte sua história',desc:'Preencha seu perfil e apresente seus projetos.',done:profileProgress()===100,href:'perfil'},{id:'assessment',title:'Descubra seu ponto de partida',desc:'Registre sua confiança em seis competências.',done:state.assessed,href:'nivel'},{id:'practice-'+weakest,title:'Pratique '+weakest,desc:'Implemente uma pequena funcionalidade e registre a evidência no GitHub.',done:!!state.tasks['practice-'+weakest]},{id:'first-job',title:'Encontre uma oportunidade',desc:'Salve uma vaga real alinhada ao seu objetivo.',done:state.jobs.length>0,href:'vagas'}]}
function pageTitle(eyebrow,title,subtitle,action=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`}
function jobRows(jobs){return jobs.map(j=>`<div class="job-row"><div class="company-icon">${esc(j.company.slice(0,1))}</div><div class="job-body"><strong>${esc(j.title)}</strong><p>${esc(j.company)} · ${esc(j.mode)} · ${esc(j.level)}</p><div class="tags">${j.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></div><div class="job-end">${j.demo?'<span class="tag">Exemplo</span>':`<strong>${esc(j.stage)}</strong><span>Salva por você</span>`}</div></div>`).join('')}
function taskRows(){return nextTasks().map(t=>`<div class="step"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''} ${t.href?'disabled':''} aria-label="${esc(t.title)}"><div><strong class="${t.done?'done':''}">${t.href?`<a href="#${t.href}">${esc(t.title)} ↗</a>`:esc(t.title)}</strong><p>${esc(t.desc)}</p></div></div>`).join('')}
function home(){const tasks=nextTasks();const completed=tasks.filter(t=>t.done).length;return pageTitle('SEU PRÓXIMO CAPÍTULO',`Vamos construir seu futuro${state.profile.name?', '+esc(state.profile.name.split(' ')[0]):''}.`,'Um espaço para evoluir, encontrar oportunidades e dar o próximo passo.', '<button class="primary" data-add>＋ Adicionar vaga</button>')+`<section class="hero"><div><div class="eyebrow">PEQUENOS PASSOS. GRANDES POSSIBILIDADES.</div><h2>Sua próxima oportunidade<br>começa na sua próxima versão.</h2><p>Conheça suas habilidades, construa um caminho e transforme evolução em oportunidades.</p><a class="primary" href="#${state.assessed?'evolucao':'nivel'}">${state.assessed?'Ver meu plano de evolução':'Descobrir meu ponto de partida'} <span>↗</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit"><span class="code-symbol">&lt;/&gt;</span></div><span class="orbit-label">BUILD. LEARN. GROW.</span></div></section><div class="stats">${[['Meu perfil',profileProgress()+'%','Preencha sua apresentação','◎'],['Habilidades mapeadas',state.assessed?'6':'0','Sua confiança, por competência','⌘'],['Oportunidades salvas',state.jobs.length,'Seu radar pessoal de vagas','▣'],['Candidaturas enviadas',state.jobs.filter(j=>['Enviada','Entrevista'].includes(j.stage)).length,'Acompanhe cada próximo passo','↗']].map(([l,v,d,i])=>`<div class="stat"><div class="stat-top">${l}<span class="stat-icon">${i}</span></div><strong>${v}</strong><small>${d}</small></div>`).join('')}</div><div class="columns"><section class="card"><div class="card-head"><h2>Seu radar de oportunidades</h2><a href="#vagas">Explorar vagas ↗</a></div>${state.jobs.length?jobRows(state.jobs.slice(-3).reverse()):state.demo?jobRows(examples):'<div class="empty"><h2>Seu radar está pronto</h2><p>Adicione a primeira vaga para começar.</p></div>'}<div class="hint">${state.jobs.length?'As vagas deste painel foram cadastradas por você.':'As oportunidades acima são fictícias, para demonstrar o painel. Cadastre vagas reais pelo botão Adicionar vaga.'}</div></section><section class="card"><div class="card-head"><h2>Seu próximo passo</h2><span class="tag">${completed} de 4 concluídos</span></div><div class="card-caption">Uma evolução possível, no seu ritmo.</div><div class="progress"><span style="width:${completed/4*100}%"></span></div>${taskRows()}</section></div><section class="card section-space"><div class="card-head"><h2>Um caminho que conecta tudo</h2><span class="tag">SEU ECOSSISTEMA</span></div><div class="form-grid"><div><strong>01 · Entenda onde você está</strong><p class="subtitle">Perfil, projetos e habilidades reunidos em um só lugar.</p></div><div><strong>02 · Vá em direção ao que você quer</strong><p class="subtitle">Um plano prático e suas candidaturas sempre à vista.</p></div></div></section>`}
function profile(){const p=state.profile;return pageTitle('SUA HISTÓRIA','Um perfil, muitas possibilidades.','Organize os dados que vão acompanhar suas próximas oportunidades.')+`<div class="notice">Seus dados ficam neste navegador. Use “Exportar meus dados” para guardar uma cópia. Preencha apenas o que quiser compartilhar nas suas candidaturas.</div><form id="profile-form" class="card"><div class="card-head"><h2>Sobre você</h2><span class="tag">${profileProgress()}% preenchido</span></div><div class="form-grid">${[['name','Seu nome','text'],['role','Cargo desejado','text'],['email','E-mail profissional','email'],['github','GitHub ou portfólio','url'],['location','Cidade / preferência de trabalho','text'],['hours','Horas de estudo por semana','number']].map(([k,l,t])=>`<label>${l}<input name="${k}" type="${t}" value="${esc(p[k])}" ${t==='number'?'min="1" max="80"':''} maxlength="200" placeholder="${k==='github'?'https://github.com/seu-usuario':l}"></label>`).join('')}</div><label>Resumo profissional<textarea name="about" maxlength="3000" placeholder="O que você já construiu, o que gosta de fazer e o que busca?">${esc(p.about)}</textarea></label><label>Projetos e evidências<textarea name="projects" maxlength="5000" placeholder="Descreva seus projetos e inclua links. Explique sua contribuição.">${esc(p.projects)}</textarea></label><button class="primary">Salvar meu perfil ↗</button></form><section class="card section-space"><div class="card-head"><h2>Apresentação para candidatura</h2><button class="secondary" id="download-resume">Baixar em texto ↓</button></div><p class="subtitle">Gerada com os dados que você preencheu. Revise antes de enviar.</p><div class="resume section-space">${esc(resume())}</div></section>`}
function resume(job){const p=state.profile;return [p.name||'Seu nome',p.role,[p.email,p.location,p.github].filter(Boolean).join(' · '),'',p.about||'Preencha seu resumo profissional no perfil.','', 'PROJETOS',p.projects||'Adicione projetos e evidências no perfil.',...(job?['',`OPORTUNIDADE DE INTERESSE: ${job.title} — ${job.company}`]:[])].join('\n')}
function assessment(){return pageTitle('AUTOCONHECIMENTO','Conheça seu ponto de partida.','Mapeie sua confiança. Cada competência tem seu próprio caminho.')+`<div class="notice">Esta é uma autoavaliação, não uma classificação de senioridade. Uma análise do seu nível profissional exige evidências de projetos, desafios e revisão de código. Aqui, 0 significa “ainda não pratiquei” e 4, “consigo implementar e explicar com autonomia”.</div><form id="skills-form" class="card"><div class="skill-grid">${skills.map((s,i)=>`<div class="skill-box"><strong>${s}</strong><span class="skill-score" id="score-${i}">${state.skills[s]} / 4</span><p>${['Estrutura semântica, layout responsivo e acessibilidade.','Lógica, eventos, assincronismo e manipulação de dados.','Componentes, estado, formulários e integração com APIs.','Rotas, validação, autenticação e tratamento de erros.','Modelagem, consultas, relacionamentos e persistência.','Versionamento, revisão de mudanças e testes úteis.'][i]}</p><input name="${s}" type="range" min="0" max="4" step="1" value="${state.skills[s]}" data-score="${i}" aria-label="Confiança em ${s}"><div class="scale"><span>Ainda não pratiquei</span><span>Tenho autonomia</span></div></div>`).join('')}</div><button class="primary section-space">Salvar e montar meu caminho ↗</button></form>`}
function evolution(){return pageTitle('PASSO A PASSO','Sua evolução tem um caminho.','Uma trilha inicial baseada na sua autoavaliação e no seu tempo disponível.')+`<div class="columns"><section class="card"><div class="card-head"><h2>Seu plano inicial</h2><span class="tag">${esc(state.profile.hours)}h por semana</span></div>${taskRows()}<div class="hint">O plano é uma sugestão inicial. Os itens de perfil, avaliação e vagas são concluídos quando você registra esses dados.</div></section><section class="card"><div class="card-head"><h2>Mapa de confiança</h2><a href="#nivel">Atualizar ↗</a></div>${skills.map(s=>`<div><div class="stat-top"><span>${s}</span><span>${state.skills[s]}/4</span></div><div class="progress"><span style="width:${state.skills[s]*25}%"></span></div></div>`).join('')}<div class="hint">${state.assessed?'Priorize uma competência e construa algo que consiga mostrar e explicar.':'Complete sua autoavaliação para personalizar o próximo exercício.'}</div></section></div>`}
function radar(){return pageTitle('ABRA NOVAS PORTAS','Oportunidades no seu radar.','Reúna as vagas que fazem sentido para o seu próximo capítulo.','<button class="primary" data-add>＋ Adicionar vaga</button>')+`<div class="jobs-toolbar"><input id="job-search" type="search" placeholder="Buscar cargo, empresa ou tecnologia…" value="${esc(query)}" aria-label="Buscar vagas"><select id="mode-filter" aria-label="Filtrar modalidade">${['Todas','Remoto','Híbrido','Presencial'].map(m=>`<option ${mode===m?'selected':''}>${m}</option>`).join('')}</select></div><div id="job-results">${radarResults()}</div><div class="notice section-space">Nesta versão, você cadastra as vagas manualmente. Busca automática, leitura de currículo e envio de candidaturas ainda não estão conectados.</div>`}
function radarResults(){const jobs=state.jobs.filter(j=>(mode==='Todas'||mode===j.mode)&&[j.title,j.company,...j.tags].join(' ').toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')));return jobs.length?jobs.slice().reverse().map(j=>`<section class="card job-card">${jobRows([j])}${j.notes?`<p class="subtitle">${esc(j.notes)}</p>`:''}<div class="job-actions section-space"><select data-stage="${j.id}" aria-label="Etapa da candidatura">${stages.map(s=>`<option ${j.stage===s?'selected':''}>${s}</option>`).join('')}</select><button class="secondary" data-resume="${j.id}">Preparar currículo ↓</button><button class="danger" data-delete="${j.id}">Excluir</button>${j.url?`<a href="${esc(j.url)}" target="_blank" rel="noopener noreferrer">Abrir vaga ↗</a>`:''}</div></section>`).join(''):`<div class="card empty"><h2>${state.jobs.length?'Nenhuma vaga neste filtro':'Sua próxima oportunidade pode começar aqui'}</h2><p>${state.jobs.length?'Tente outro cargo ou modalidade.':'Encontrou uma vaga interessante? Salve o link, a empresa e os requisitos.'}</p><button class="primary" data-add>＋ Adicionar vaga</button></div>`}
function applications(){return pageTitle('CADA PASSO CONTA','Suas candidaturas, à vista.','Mude a etapa conforme o processo avança. O envio é registrado manualmente.','<button class="primary" data-add>＋ Adicionar vaga</button>')+`<div class="board">${stages.filter(s=>s!=='Encerrada').map(s=>`<section class="board-col"><h2>${s}<span>${state.jobs.filter(j=>j.stage===s).length}</span></h2>${state.jobs.filter(j=>j.stage===s).map(boardCard).join('')||'<p class="board-empty">Novos passos aparecerão aqui.</p>'}</section>`).join('')}</div>${state.jobs.some(j=>j.stage==='Encerrada')?`<section class="card section-space"><h2>Processos encerrados</h2>${state.jobs.filter(j=>j.stage==='Encerrada').map(boardCard).join('')}</section>`:''}`}
function boardCard(j){return `<div class="board-card"><strong>${esc(j.title)}</strong><p>${esc(j.company)} · ${esc(j.mode)}</p><select data-stage="${j.id}" aria-label="Etapa de ${esc(j.title)}">${stages.map(s=>`<option ${j.stage===s?'selected':''}>${s}</option>`).join('')}</select></div>`}
function render(){view=location.hash.slice(1)||'inicio';if(!routes.some(r=>r[0]===view))view='inicio';$('nav').innerHTML=routes.map(([id,icon,label])=>`<a href="#${id}" class="${id===view?'active':''}" ${id===view?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}${id==='vagas'?`<span class="count">${state.jobs.length}</span>`:''}</a>`).join('');$('#page-name').textContent=routes.find(r=>r[0]===view)[2];$('#side-name').textContent=state.profile.name||'Seu perfil';document.querySelectorAll('.avatar').forEach(el=>el.textContent=(state.profile.name||'D')[0].toUpperCase());$('#main').innerHTML=({inicio:home,perfil:profile,nivel:assessment,evolucao:evolution,vagas:radar,candidaturas:applications})[view]();}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-add'))$('#dialog').showModal();if(b.id==='close-dialog')$('#dialog').close();if(b.id==='profile-shortcut')location.hash='perfil';if(b.id==='export')download('dev-master-backup.json',JSON.stringify(state,null,2),'application/json');if(b.id==='download-resume')download('curriculo-dev-master.txt',resume());if(b.dataset.resume){const job=state.jobs.find(j=>j.id===b.dataset.resume);download('curriculo-candidatura.txt',resume(job));toast('Currículo em texto preparado. Revise antes de enviar.')}if(b.dataset.delete){if(confirm('Excluir esta oportunidade e seu acompanhamento?')){state.jobs=state.jobs.filter(j=>j.id!==b.dataset.delete);save();render();toast('Oportunidade excluída.')}}});
document.addEventListener('input',e=>{if(e.target.dataset.score){$('#score-'+e.target.dataset.score).textContent=e.target.value+' / 4'}if(e.target.id==='job-search'){query=e.target.value;$('#job-results').innerHTML=radarResults()}});
document.addEventListener('change',e=>{if(e.target.dataset.stage){const job=state.jobs.find(j=>j.id===e.target.dataset.stage);job.stage=e.target.value;save();render();toast('Etapa atualizada.')}if(e.target.dataset.task){state.tasks[e.target.dataset.task]=e.target.checked;save();render()}if(e.target.id==='mode-filter'){mode=e.target.value;$('#job-results').innerHTML=radarResults()}});
document.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(e.target.id==='profile-form'){state.profile=data;save();render();toast('Seu perfil foi salvo.')}if(e.target.id==='skills-form'){skills.forEach(s=>state.skills[s]=Number(data[s]));state.assessed=true;save();location.hash='evolucao';toast('Seu ponto de partida foi registrado.')}if(e.target.id==='job-form'){let url=data.url.trim();if(url&&!/^https?:\/\//i.test(url)){toast('Use um link que comece com https:// ou http://.');return}if(!data.title.trim()||!data.company.trim()){toast('Preencha o cargo e a empresa.');return}state.jobs.push({...data,title:data.title.trim(),company:data.company.trim(),url,tags:data.tags.split(',').map(s=>s.trim()).filter(Boolean).slice(0,12),id:crypto.randomUUID(),stage:'Salva',createdAt:new Date().toISOString()});state.demo=false;save();$('#dialog').close();e.target.reset();if(view==='vagas')render();else location.hash='vagas';toast('Oportunidade adicionada ao seu radar.')}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
